1	import { Dataset, Review, ReviewsResponse, Summary, RateLimitStatus, ChatMessage } from '@/types'
2	
3	const API_BASE = '/api/v1'
4	
5	function getToken(): string | null {
6	  if (typeof window === 'undefined') return null
7	  return sessionStorage.getItem('rl_token')
8	}
9	
10	async function apiFetch<T>(path: string, options: RequestInit = {}): Promise<T> {
11	  const token = getToken()
12	  const headers: Record<string, string> = {
13	    'Content-Type': 'application/json',
14	    ...(options.headers as Record<string, string> || {}),
15	  }
16	  if (token) headers['Authorization'] = `Bearer ${token}`
17	
18	  const res = await fetch(`${API_BASE}${path}`, { ...options, headers })
19	
20	  if (res.status === 401) {
21	    sessionStorage.removeItem('rl_token')
22	    sessionStorage.removeItem('rl_user')
23	    window.location.href = '/login?expired=1'
24	    throw new Error('Unauthorized')
25	  }
26	
27	  if (!res.ok) {
28	    const err = await res.json().catch(() => ({ message: 'Request failed' }))
29	    throw Object.assign(new Error(err.message || 'Request failed'), { status: res.status, data: err })
30	  }
31	
32	  if (res.status === 204) return undefined as T
33	  return res.json()
34	}
