36	// Auth
37	export const authApi = {
38	  login: async (email: string, password: string) => {
39	    const res = await fetch(`${API_BASE}/auth/login`, {
40	      method: 'POST',
41	      headers: { 'Content-Type': 'application/json' },
42	      body: JSON.stringify({ email, password }),
43	    })
44	    if (!res.ok) {
45	      const err = await res.json().catch(() => ({ message: 'Login failed' }))
46	      throw Object.assign(new Error(err.message || 'Login failed'), { status: res.status, data: err })
47	    }
48	    return res.json() as Promise<{ token: string; expires_at: string; user: { id: string; email: string } }>
49	  },
50	  logout: () => apiFetch<void>('/auth/logout', { method: 'POST' }),
51	}
52	
53	// Datasets
54	export const datasetsApi = {
55	  list: () => apiFetch<{ datasets: Dataset[] }>('/datasets'),
56	  get: (id: string) => apiFetch<Dataset>(`/datasets/${id}`),
57	  create: (input: string) =>
58	    apiFetch<{ id: string; asin: string; status: string }>('/datasets', {
59	      method: 'POST',
60	      body: JSON.stringify({ input }),
61	    }),
62	  upload: async (file: File): Promise<{ id: string; status: string }> => {
63	    const token = getToken()
64	    const headers: Record<string, string> = {}
65	    if (token) headers['Authorization'] = `Bearer ${token}`
66	    const body = new FormData()
67	    body.append('file', file)
68	    const res = await fetch(`${API_BASE}/datasets/upload`, { method: 'POST', headers, body })
69	    if (res.status === 401) {
70	      sessionStorage.removeItem('rl_token')
71	      sessionStorage.removeItem('rl_user')
72	      window.location.href = '/login?expired=1'
73	      throw new Error('Unauthorized')
74	    }
75	    if (!res.ok) {
76	      const err = await res.json().catch(() => ({ message: 'Upload failed' }))
77	      throw Object.assign(new Error(err.message || 'Upload failed'), { status: res.status, data: err })
78	    }
79	    return res.json()
80	  },
81	  rescrape: (id: string) =>
82	    apiFetch<{ status: string }>(`/datasets/${id}/rescrape`, { method: 'POST' }),
83	  delete: (id: string) => apiFetch<void>(`/datasets/${id}`, { method: 'DELETE' }),
84	}
85	
86	// Reviews & Summary
87	export const reviewsApi = {
88	  list: (id: string, params: Record<string, string | number>) => {
89	    const qs = new URLSearchParams(Object.entries(params).map(([k, v]) => [k, String(v)])).toString()
90	    return apiFetch<ReviewsResponse>(`/datasets/${id}/reviews?${qs}`)
91	  },
92	  summary: (id: string) => apiFetch<Summary>(`/datasets/${id}/summary`),
93	}
94	
95	// Rate limit
96	export const scrapeApi = {
97	  rateLimit: () => apiFetch<RateLimitStatus>('/scrape/rate-limit'),
98	}
99	
100	// Chat
101	export const chatApi = {
102	  send: (datasetId: string, message: string, history: ChatMessage[]) =>
103	    apiFetch<{ reply: string; scope_refused: boolean }>(`/datasets/${datasetId}/chat`, {
104	      method: 'POST',
105	      body: JSON.stringify({
106	        message,
107	        history: history.map(h => ({ role: h.role, content: h.content })),
108	      }),
109	    }),
110	}
